<script>
 import {onMount,onDestroy,untrack} from 'svelte';
 import {renderManualClip,clipInterval,paintClipFrame,recordingMime,keepClipValues} from '../../lib/manual-clip-render.js';
 import {uploadClipMedia} from '../../lib/clip-media-client.js';
 let {source,recordingId,request,proposedMoment=null,selectedClipId='',onClipChange=()=>{},onDirtyChange=()=>{}}=$props();
 let library=$state({assets:[],proposals:[],artifacts:[]}),sourceAssetId=$state(''),audioAssetId=$state(''),proposalId=$state(''),proposalRevision=$state(0),start=$state(0),end=$state(15),cropX=$state(.5),cropY=$state(.5),caption=$state(''),videoGain=$state(1),audioGain=$state(.7),base=$state(''),revisionNeedsSave=$state(false);
 let sourceFile=$state(null),audioFile=$state(null),videoBlob=$state(null),audioBlob=$state(null),sourceUrl=$state(''),renderUrl=$state(''),savedUrl=$state(''),renderBlob=$state(null),renderIdentity=$state(''),rights=$state(''),duration=$state(0),busy=$state(''),error=$state(''),previewError=$state(''),notice=$state(''),progress=$state(0),pending=$state(null),video=$state(null),canvas=$state(null);
 let clipOpen=$state(false),appliedMoment=$state('');
 let alive=true,sequence=0,controller;const sourceAssets=$derived(library.assets.filter(a=>a.kind==='source')),audioAssets=$derived(library.assets.filter(a=>a.kind==='audio'));
 const values=()=>({sourceId:source.id,recordingId,sourceAssetId,...(audioAssetId?{audioAssetId}:{}),startSeconds:Number(start),endSeconds:Number(end),cropX:Number(cropX),cropY:Number(cropY),caption,videoGain:Number(videoGain),audioGain:Number(audioGain)});
 const renderKey=$derived(JSON.stringify({proposalId,proposalRevision,proposal:values()}));
 $effect(()=>{const key=renderKey;if(renderBlob&&renderIdentity!==key){renderBlob=null;renderIdentity='';untrack(()=>replaceUrl('render',null));}});
 const proposalDirty=$derived(revisionNeedsSave||base!==JSON.stringify(values()));const dirty=$derived(Boolean(sourceFile||audioFile||renderBlob||pending)||proposalDirty&&Boolean(base));
 const savedProposal=$derived(library.proposals.find(p=>p.id===proposalId));
 const selectedArtifact=$derived(library.artifacts.find(a=>a.id===selectedClipId));
 $effect(()=>onDirtyChange(dirty));
 function replaceUrl(kind,blob){const key=kind==='source'?sourceUrl:kind==='saved'?savedUrl:renderUrl;if(key)URL.revokeObjectURL(key);const next=blob?URL.createObjectURL(blob):'';if(kind==='source')sourceUrl=next;else if(kind==='saved')savedUrl=next;else renderUrl=next;}
 function redraw(){if(canvas&&video?.readyState>=2){try{paintClipFrame(canvas,video,values());previewError='';}catch(e){previewError=e.message;}}}
 $effect(()=>{start;end;cropX;cropY;caption;untrack(redraw);});
 async function load(){const result=await request('/inbox/clips?sourceId='+encodeURIComponent(source.id));if(alive)library=result;}
 async function chooseAsset(kind,id){if(busy||pending)return;error='';const ticket=++sequence;busy='Loading media';try{const blob=id?await request('/inbox/clips/assets/'+encodeURIComponent(id),{responseType:'blob'}):null;if(!alive||ticket!==sequence)return;if(kind==='source'){sourceAssetId=id;sourceFile=null;videoBlob=blob;replaceUrl('source',blob);}else{audioAssetId=id;audioFile=null;audioBlob=blob;}}catch(e){if(alive)error=e.message;}finally{if(alive&&ticket===sequence)busy='';}}
 function fileChosen(kind,file){if(!file)return;const max=kind==='source'?20*1024*1024:6*1024*1024;if(file.size>max){error=kind==='source'?'Choose an MP4 no larger than 20 MiB.':'Choose a WAV no larger than 6 MiB.';return;}error='';if(kind==='source'){sourceFile=file;sourceAssetId='';videoBlob=file;replaceUrl('source',file);}else{audioFile=file;audioAssetId='';audioBlob=file;}}
 async function upload(kind){if(busy)return;const file=kind==='source'?sourceFile:audioFile;if(!file||!rights.trim())return;pending ||= {kind,key:crypto.randomUUID(),blob:file,metadata:{kind,name:file.name.slice(0,160),contentType:kind==='source'?'video/mp4':'audio/wav',rightsDeclaration:rights.trim(),sourceId:source.id,...(recordingId?{recordingId}:{})}};await finishUpload();}
 async function finishUpload(){if(!pending||busy)return;busy='Uploading '+pending.kind;progress=0;error='';try{const result=await uploadClipMedia(request,pending.blob,pending.metadata,pending.key,v=>progress=v);if(!alive)return;const kind=pending.kind;pending=null;if(kind==='source'){sourceAssetId=result.asset.id;sourceFile=null;}else if(kind==='audio'){audioAssetId=result.asset.id;audioFile=null;}else{renderBlob=null;replaceUrl('render',null);onClipChange(result.artifact.id);notice='MP4 saved. Reopen it below or include it in your report.';}await load();}catch(e){if(alive){error=e.message;if(e.status>=400&&e.status<500)pending=null;}}finally{if(alive)busy='';}}
 function loadedVideo(){duration=video.duration;if(!proposalId&&!appliedMoment)end=Math.min(15,duration);redraw();}
 $effect(()=>{const moment=proposedMoment;if(moment?.selectionKey&&moment.selectionKey!==appliedMoment)untrack(()=>{if(dirty||busy||pending){error='Save or discard your working segment before using another proposed moment.';return;}start=moment.startSeconds;end=moment.endSeconds;appliedMoment=moment.selectionKey;clipOpen=true;notice='Saved proposed times applied. Check them against your permitted source file; discard segment changes to undo without uploading.'+(moment.recordingId&&moment.recordingId!==recordingId?' Proposed recording: '+(moment.recordingTitle||moment.recordingId)+'. Your saved catalog match is unchanged.':'');});});
 async function saveProposal(){if(busy||pending)return;try{clipInterval(start,end,duration);}catch(e){error=e.message;return;}const proposal={...values(),...(proposalId?{id:proposalId,expectedProposalRevision:proposalRevision}:{})};pending={kind:'proposal',key:crypto.randomUUID(),proposal};await finishProposal();}
 async function finishProposal(){if(busy||pending?.kind!=='proposal')return;busy='Saving segment';error='';try{const result=await request('/inbox/clips/proposals',{method:'POST',body:JSON.stringify({idempotencyKey:pending.key,proposal:pending.proposal})});if(!alive)return;proposalId=result.proposal.id;proposalRevision=result.proposal.revision;base=JSON.stringify(values());revisionNeedsSave=false;pending=null;notice='Segment saved. Render its actual video and audio next.';await load();}catch(e){if(alive){error=e.message;if(e.status>=400&&e.status<500)pending=null;}}finally{if(alive)busy='';}}
 async function openProposal(p){if(!p||dirty||busy)return;proposalId=p.id;proposalRevision=p.revision;start=p.startSeconds;end=p.endSeconds;cropX=p.cropX;cropY=p.cropY;caption=p.caption;videoGain=p.videoGain;audioGain=p.audioGain;await chooseAsset('source',p.sourceAssetId);await chooseAsset('audio',p.audioAssetId||'');if(alive){base=JSON.stringify(values());revisionNeedsSave=false;}}
 function keepValues(){if(!savedProposal||busy||pending)return;const rebase=keepClipValues(values(),savedProposal);proposalRevision=rebase.revision;base=rebase.base;revisionNeedsSave=rebase.requiresSave;notice='Your values are retained. Save segment before rendering.';}
 async function render(){if(busy||proposalDirty||!proposalId)return;busy='Rendering MP4';error='';progress=0;controller=new AbortController();const identity=renderKey;video?.pause();try{const blob=await renderManualClip({videoBlob,audioBlob,proposal:values(),signal:controller.signal,onProgress:value=>progress=value});if(!alive)return;if(identity!==renderKey)throw Error('The segment changed during rendering. Render the saved segment again.');renderIdentity=identity;renderBlob=blob;replaceUrl('render',blob);notice='MP4 rendered in this browser. Play it before saving.';}catch(e){if(alive)error=e.message;}finally{if(alive)busy='';controller=null;}}
 async function saveRender(){if(!renderBlob||!proposalId||proposalDirty||renderIdentity!==renderKey||busy)return;const sourceAsset=library.assets.find(a=>a.id===sourceAssetId),audioAsset=library.assets.find(a=>a.id===audioAssetId);pending={kind:'render',key:crypto.randomUUID(),blob:renderBlob,metadata:{kind:'render',name:'clip-'+source.id+'.mp4',contentType:'video/mp4',rightsDeclaration:sourceAsset?.rightsDeclaration||rights,sourceId:source.id,recordingId,proposalId,proposalRevision,inputHashes:{source:sourceAsset.sha256,audio:audioAsset?.sha256||null}}};await finishUpload();}
 function mediaPath(value){const url=new URL(value,window.location.origin);const match=url.pathname.match(/\/inbox\/clips\/assets\/([A-Za-z0-9_:-]{1,128})$/);if(url.origin!==window.location.origin||url.search||url.hash||!match)throw Error('The saved clip link is unavailable.');return '/inbox/clips/assets/'+encodeURIComponent(match[1]);}
 async function discard(){if(busy||pending)return;const previous=JSON.parse(base);sourceFile=null;audioFile=null;renderBlob=null;replaceUrl('render',null);start=previous.startSeconds;end=previous.endSeconds;cropX=previous.cropX;cropY=previous.cropY;caption=previous.caption;videoGain=previous.videoGain;audioGain=previous.audioGain;await chooseAsset('source',previous.sourceAssetId);await chooseAsset('audio',previous.audioAssetId||'');revisionNeedsSave=false;error='';}
 async function reopen(artifact){if(busy||dirty)return;busy='Opening saved MP4';error='';try{const blob=await request(artifact.assetId?'/inbox/clips/assets/'+encodeURIComponent(artifact.assetId):mediaPath(artifact.url),{responseType:'blob'});if(!alive)return;replaceUrl('saved',blob);onClipChange(artifact.id);}catch(e){if(alive)error=e.message;}finally{if(alive)busy='';}}
 onMount(()=>{void load().then(()=>{if(alive){base=JSON.stringify(values());const existing=library.artifacts.find(a=>a.id===selectedClipId);if(existing)void reopen(existing);}}).catch(e=>{if(alive)error=e.message;});});
 onDestroy(()=>{alive=false;sequence++;controller?.abort();for(const url of [sourceUrl,renderUrl,savedUrl])if(url)URL.revokeObjectURL(url);onDirtyChange(false);});
</script>
<details class="clip" aria-label="Create a source clip" bind:open={clipOpen}><summary>Make a short from your files</summary><header><p>Use an MP4 you can use and a permitted WAV recording. Your source link and proposed match stay attached.</p></header>
 {#if error}<p role="alert">{error}</p><button disabled={Boolean(busy||pending)} onclick={()=>load()}>Reload saved segments</button>{/if}{#if previewError}<p role="alert">{previewError}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if busy}<p role="status">{busy}{progress?` · ${Math.round(progress*100)}%`:''}</p>{#if busy==='Rendering MP4'}<button onclick={()=>controller?.abort()}>Cancel render</button>{/if}{/if}
 {#if pending&&!busy}<button onclick={()=>pending.kind==='proposal'?finishProposal():finishUpload()}>Retry same {pending.kind==='proposal'?'segment save':'upload'}</button>{/if}
 <fieldset disabled={Boolean(busy||pending)}><legend>1. Supply the media</legend><label>Source MP4<input type="file" accept="video/mp4,.mp4" onchange={e=>{fileChosen('source',e.currentTarget.files?.[0]);e.currentTarget.value='';}}/></label>{#if sourceAssets.length}<label>Saved source video<select value={sourceAssetId} onchange={e=>chooseAsset('source',e.currentTarget.value)}><option value="">Choose a saved MP4</option>{#each sourceAssets as a(a.id)}<option value={a.id}>{a.name}</option>{/each}</select></label>{/if}<label>Recording WAV<input type="file" accept="audio/wav,.wav" onchange={e=>{fileChosen('audio',e.currentTarget.files?.[0]);e.currentTarget.value='';}}/></label>{#if audioAssets.length}<label>Saved recording audio<select value={audioAssetId} onchange={e=>chooseAsset('audio',e.currentTarget.value)}><option value="">Choose a saved WAV</option>{#each audioAssets as a(a.id)}<option value={a.id}>{a.name}</option>{/each}</select></label>{/if}<label>Source and permission note<textarea bind:value={rights} rows="2" maxlength="1000" placeholder="Describe where these files came from and your permission to use them."></textarea></label><button disabled={!sourceFile||!rights.trim()} onclick={()=>upload('source')}>Save supplied video</button><button disabled={!audioFile||!rights.trim()} onclick={()=>upload('audio')}>Save supplied audio</button></fieldset>
 {#if sourceUrl}<div class="previews"><div><h5>Source video</h5><video bind:this={video} src={sourceUrl} controls playsinline preload="metadata" onloadeddata={loadedVideo} ontimeupdate={redraw}><track kind="captions"/></video><button disabled={Boolean(busy)} onclick={()=>{start=Math.round(video.currentTime*100)/100;end=Math.min(duration,Number(start)+15);}}>Use current time as start</button></div><div><h5>9:16 crop and caption</h5><canvas bind:this={canvas} width="1080" height="1920" aria-label="Current cropped source frame and caption"></canvas></div></div>{/if}
 <fieldset disabled={Boolean(busy||pending)}><legend>2. Choose the moment</legend>{#if savedProposal&&savedProposal.revision!==proposalRevision}<p>A newer segment is saved. Your working values are retained.</p><button onclick={keepValues}>Keep my values on the current revision</button>{/if}{#if library.proposals.length}<label>Saved segment<select value={proposalId} disabled={dirty} onchange={e=>openProposal(library.proposals.find(p=>p.id===e.currentTarget.value))}><option value="" disabled>Choose a saved segment</option>{#each library.proposals as p(p.id)}<option value={p.id}>Segment {p.startSeconds}–{p.endSeconds}s · revision {p.revision}</option>{/each}</select></label>{/if}<div class="numbers"><label>Start (seconds)<input type="number" min="0" max={duration||undefined} step="0.1" bind:value={start}/></label><label>End (seconds)<input type="number" min="0" max={duration||undefined} step="0.1" bind:value={end}/></label></div><p>Choose up to 30 seconds. Supplied audio starts at the beginning of the clip.</p><label>Crop left to right<input type="range" min="0" max="1" step="0.01" bind:value={cropX}/></label><label>Crop top to bottom<input type="range" min="0" max="1" step="0.01" bind:value={cropY}/></label><label>Caption<textarea rows="2" maxlength="160" bind:value={caption}></textarea></label><div class="numbers"><label>Source audio (%)<input type="number" min="0" max="200" step="10" value={Math.round(videoGain*100)} oninput={e=>videoGain=Number(e.currentTarget.value)/100}/></label><label>Recording audio (%)<input type="number" min="0" max="200" step="10" value={Math.round(audioGain*100)} oninput={e=>audioGain=Number(e.currentTarget.value)/100}/></label></div><button disabled={!sourceAssetId||!recordingId||!proposalDirty||Boolean(sourceFile||audioFile)||Boolean(previewError)} onclick={saveProposal}>Save segment</button></fieldset>
 <section aria-label="Rendered clip"><h4>3. Render and keep the MP4</h4><p>Rendering plays the selected media in real time. Keep this tab active.</p><button disabled={Boolean(busy||pending)||!proposalId||proposalDirty||!videoBlob||Boolean(previewError)||!recordingMime()} onclick={render}>Render 9:16 MP4</button>{#if !recordingMime()}<p>This browser does not support MP4 recording. Your saved segment is retained.</p>{/if}{#if renderUrl}<video src={renderUrl} controls playsinline aria-label="Rendered MP4 preview"><track kind="captions"/></video><button disabled={Boolean(busy||pending)||proposalDirty} onclick={saveRender}>Save rendered MP4</button>{/if}{#if library.artifacts.length}<h5>Saved MP4 clips</h5>{#each library.artifacts as artifact(artifact.id)}<button disabled={Boolean(busy)||dirty} onclick={()=>reopen(artifact)} aria-pressed={selectedClipId===artifact.id}>Open saved clip · {new Date(artifact.createdAt).toLocaleString()}</button>{/each}{/if}{#if savedUrl}<video src={savedUrl} controls playsinline aria-label="Saved MP4 clip"><track kind="captions"/></video><a href={savedUrl} download={`clip-${selectedArtifact?.id||source.id}.mp4`}>Download MP4</a><p>The saved clip is selected for your report below. Download to share; it is not published automatically.</p>{/if}</section>
 {#if dirty&&!pending&&!busy}<button class="secondary" onclick={discard}>Discard segment changes</button>{/if}
</details>
<style>.clip{border-top:1px solid #dedfd8;margin-top:20px;padding-top:16px}.clip>summary{cursor:pointer;font-weight:650;font-size:16px}.clip h4{font-size:17px;margin:8px 0}.clip p{font-size:13px;line-height:1.6}.clip label{display:block;margin:10px 0;font-size:13px}.clip input,.clip textarea,.clip select{display:block;width:100%;margin-top:5px}.clip fieldset{margin:16px 0;border:1px solid #dedfd8;padding:12px}.clip legend{font-weight:650}.clip button{margin:4px 8px 4px 0}.numbers{display:flex;gap:14px}.numbers label{flex:1;min-width:0}.previews{display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:start}video{width:100%;max-height:400px;background:#111}canvas{width:100%;max-height:400px;object-fit:contain;background:#111}.clip h5{margin:8px 0}@media(max-width:600px){.previews{grid-template-columns:1fr}.numbers{flex-wrap:wrap}}</style>
